    <span ref={startRef}>{start}</span>
    <span ref={nowRef} className={cn("absolute -translate-x-1/2", !showNow && "invisible")} style={{ left: `${elapsedPercent}%` }}>{now}</span>
    <span ref={resetRef}>{reset}</span>
  </div>;
}
